task he_42__incr_list(l: seq) returns (r: seq)
  ensures len(r) == len(l)
  ensures forall i in [0, len(l)) . r[i] == l[i] + 1
{
  r := [];
  var i: int := 0;
  while i < len(l)
    invariant 0 <= i
    invariant i <= len(l)
    invariant len(r) == i
    invariant forall j in [0, i) . r[j] == l[j] + 1
    decreases len(l) - i
  {
    r := r + [l[i] + 1];
    i := i + 1;
  }
}

